import fs from "node:fs/promises";
import path from "node:path";
import { createHash } from "node:crypto";
import { annotateSubskills } from "./lib/annotate-subskills.mjs";
async function writeIfDifferent(filename, contents) {
  try {
    if ((await fs.readFile(filename, "utf8")) === contents) return;
  } catch {}
  await fs.writeFile(filename, contents);
}
await annotateSubskills();
const root = path.resolve("apps/showcase/src/content");
const header =
  "// Generated by scripts/build-content-index.mjs. Do not edit.\n";
const exerciseFiles = (await fs.readdir(path.join(root, "exercises")))
  .filter((f) => f.endsWith(".json"))
  .sort();
const lessonFiles = (await fs.readdir(path.join(root, "lessons")))
  .filter((f) => f.endsWith(".json"))
  .sort();
let runtime = header + "import type { Lesson } from './model.ts';\n";
runtime +=
  exerciseFiles
    .map(
      (f, n) => `import e${n} from './exercises/${f}' with { type: 'json' };`,
    )
    .join("\n") + "\n";
runtime += `export const exerciseData = [${exerciseFiles.map((_, n) => `...e${n}`).join(", ")}];\n`;
const loaders = [];
for (const f of lessonFiles) {
  const data = JSON.parse(
    await fs.readFile(path.join(root, "lessons", f), "utf8"),
  );
  loaders.push(
    `  '${data.topicId}': () => import('./lessons/${f}').then(m => m.default as Lesson)`,
  );
}
runtime += `export const lessonLoaders: Record<string, () => Promise<Lesson>> = {\n${loaders.join(",\n")}\n};\n`;
const library =
  header +
  lessonFiles
    .map((f, n) => `import l${n} from './lessons/${f}' with { type: 'json' };`)
    .join("\n") +
  `\nexport const lessonData = [${lessonFiles.map((_, n) => `l${n}`).join(", ")}];\n`;
await writeIfDifferent(path.join(root, "generated.ts"), runtime);
await writeIfDifferent(
  path.join(root, "lesson-loaders.ts"),
  header +
    "import type { Lesson } from './model.ts';\n" +
    `export const lessonLoaders: Record<string, () => Promise<Lesson>> = {\n${loaders.join(",\n")}\n};\n`,
);
const lessonSearchMetadataKeys = new Set([
  "type",
  "kind",
  "id",
  "ids",
  "revision",
  "anchor",
  "anchors",
  "path",
  "paths",
  "url",
  "urls",
  "href",
]);
const lessonSearch = [];
for (const filename of lessonFiles) {
  const lesson = JSON.parse(
    await fs.readFile(path.join(root, "lessons", filename), "utf8"),
  );
  for (const section of lesson.sections) {
    const strings = [];
    function collect(value) {
      if (typeof value === "string") strings.push(value);
      else if (Array.isArray(value)) value.forEach(collect);
      else if (value && typeof value === "object") {
        for (const [key, child] of Object.entries(value)) {
          // Keep displayed prose/options while excluding renderer and link metadata.
          if (
            lessonSearchMetadataKeys.has(key.toLowerCase()) ||
            /(?:Id|Ids|Path|Paths|Anchor|Anchors|Url|Urls|Revision)$/u.test(key)
          )
            continue;
          collect(child);
        }
      }
    }
    collect(section.blocks);
    lessonSearch.push({
      topicId: lesson.topicId,
      revision: lesson.revision,
      sectionId: section.id,
      title: section.title,
      text: strings.join(" "),
    });
  }
}
await writeIfDifferent(
  path.join(root, "lesson-search.json"),
  JSON.stringify(lessonSearch) + "\n",
);
await writeIfDifferent(path.join(root, "generated-library.ts"), library);
const index = [];
const collections = [];
const searchIndex = [];
await fs.mkdir(path.join(root, "shards"), { recursive: true });
for (const filename of exerciseFiles) {
  const items = JSON.parse(
    await fs.readFile(path.join(root, "exercises", filename), "utf8"),
  );
  for (const item of items)
    index.push(
      Object.fromEntries(
        [
          "id",
          "slug",
          "revision",
          "title",
          "topicTitle",
          "topicId",
          "exam",
          "skillId",
          "skillIds",
          "rulePaths",
          "originCategory",
          "subtopic",
          "taskLine",
          "format",
          "level",
          "sourceTextId",
        ]
          .filter((key) => item[key] !== undefined)
          .map((key) => [key, item[key]]),
      ),
    );
  for (const item of items) {
    const entry = index.find((value) => value.id === item.id);
    entry.provenanceMethod = item.provenance.method;
    entry.generationEligible =
      item.exam === "OGE" &&
      !!item.taskLine &&
      item.examModel.year === 2027 &&
      item.examModel.status === "project" &&
      item.reviewStatus === "checked-demo" &&
      !!item.provenance.rightsBasis &&
      item.source.rightsStatus !== "unknown" &&
      ["answer-checked", "explanation-checked", "publication-approved"].every(
        (stage) => item.reviewStages?.some((r) => r.stage === stage),
      );
    searchIndex.push({
      id: item.id,
      text: [
        item.title,
        item.topicTitle,
        item.subtopic,
        item.prompt,
        item.text,
        ...item.options,
      ]
        .filter(Boolean)
        .join(" "),
    });
  }
  for (let offset = 0; offset < items.length; offset += 20) {
    const part = items.slice(offset, offset + 20),
      shardName = filename.replace(
        ".json",
        "-" + String(offset / 20 + 1) + ".json",
      );
    await writeIfDifferent(
      path.join(root, "shards", shardName),
      JSON.stringify(part) + "\n",
    );
    collections.push({
      filename: shardName,
      ids: part.map((item) => item.id),
      lines: [
        ...new Set(
          part
            .filter((item) => item.exam === "OGE")
            .map((item) => item.taskLine)
            .filter(Boolean),
        ),
      ],
    });
  }
}
await writeIfDifferent(
  path.join(root, "exercise-search.json"),
  JSON.stringify(searchIndex) + "\n",
);
await writeIfDifferent(
  path.join(root, "exercise-index.json"),
  JSON.stringify(index) + "\n",
);
await writeIfDifferent(
  path.join(root, "exercise-loaders.ts"),
  header +
    "import type { Exercise } from './model.ts';\n" +
    `export const collections = [\n${collections.map((c) => ` { ids: ${JSON.stringify(c.ids)}, lines: ${JSON.stringify(c.lines)}, load: () => import('./shards/${c.filename}').then(m => m.default as Exercise[]) }`).join(",\n")}\n];\n`,
);
const catalogHash = createHash("sha256");
for (const filename of exerciseFiles)
  catalogHash.update(
    JSON.stringify(
      JSON.parse(
        await fs.readFile(path.join(root, "exercises", filename), "utf8"),
      ),
    ),
  );
const ogeRoot = path.resolve(root, "../oge");
catalogHash.update(
  JSON.stringify(
    JSON.parse(await fs.readFile(path.join(ogeRoot, "materials.json"), "utf8")),
  ),
);
await writeIfDifferent(
  path.join(root, "catalog-version.json"),
  JSON.stringify({
    schemaVersion: 1,
    version: catalogHash.digest("hex"),
    itemCount: index.filter((e) => e.exam === "OGE" && e.taskLine).length,
  }) + "\n",
);
const materials = JSON.parse(
  await fs.readFile(path.join(ogeRoot, "materials.json"), "utf8"),
);
const activities = JSON.parse(
  await fs.readFile(path.join(ogeRoot, "activities.json"), "utf8"),
);
await writeIfDifferent(
  path.join(ogeRoot, "catalog.json"),
  JSON.stringify({
    writing: materials.writing.map(({ id, line, title }) => ({
      id,
      line,
      title,
    })),
    variants: materials.variants.map(({ id, number, title, kind }) => ({
      id,
      number,
      title,
      kind,
    })),
    activities: activities.map(({ id, title, description, situations }) => ({
      id,
      title,
      description,
      situationCount: situations.length,
      situations: situations.map((s) => ({
        id: s.id,
        revision: s.revision ?? 1,
      })),
    })),
  }) + "\n",
);
console.log("Индекс уроков и упражнений обновлён.");
